function heading(title,description,extra=''){return `<div class="page-heading"><div><h1>${e(title)}</h1><p>${e(description)}</p></div>${extra}</div>`;}
function dayLabel(){return `<div class="date-label">${icon('calendar')}<span>${e(new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date()))}</span></div>`;}
function empty(title,description,action=''){return `<div class="empty-state"><span class="empty-icon">${icon('leaf')}</span><strong>${e(title)}</strong><p>${e(description)}</p>${action}</div>`;}
