function recordItem(record){return `<div class="record-item" data-record="${Number(record.id)}" role="button" tabindex="0" aria-label="查看记录：${e(record.title)}">${sourceIcon(record)}<div class="record-body"><span class="record-title">${e(record.title||'未命名记录')}</span><p class="record-excerpt">${e(record.content||record.original_content||'暂无补充内容')}</p><div class="record-meta">${record.customer_name?`<span class="customer-label">${e(record.customer_name)}</span>`:'<span>未关联客户</span>'}<span>${e(sources[record.source]||'记录')}</span>${record.category?`<span>${e(categories[record.category]||'一般备忘')}</span>`:''}<span>${e(formatDate(record.created_at))}</span></div></div><div class="record-status">${badge(recordStatus(record),record.status)}</div></div>`;}

function upcomingItem(task){return `<div class="upcoming-item"><span class="task-dot ${task.remind_at<Date.now()/1000?'overdue':''}"></span><div class="time-block">${e(clock(task.remind_at))}<small>${e(shortDate(task.remind_at))}</small></div><div class="task-body">${task.record_id?`<button class="inline-link" data-record="${Number(task.record_id)}">${e(task.title)}</button>`:`<strong>${e(task.title)}</strong>`}<p>${e(task.customer_name||'未关联客户')} · 预计 ${e(task.duration_minutes||30)} 分钟</p></div></div>`;}
function actionBoard(queues={}){
  const names={overdue:'逾期待处理',today:'今天要做',pending_schedule:'日程待确认',needs_time:'待补时间'};
  const getItems=key=>Array.isArray(queues[key])?queues[key]:(queues[key]?.items||[]),count=key=>queues[key]?.total??getItems(key).length;
  const selected=Object.hasOwn(names,state.actionBucket)?state.actionBucket:'overdue';
  const items=getItems(selected);return `<section class="action-board"><h2>先处理哪件事</h2><p class="form-hint">逾期事项会一直留在这里，处理后才移出。自己的执行时间未定，先补安排再确认；等待反馈可在客户工作台查看。</p><div class="action-tabs">${Object.entries(names).map(([key,name])=>`<button class="button" data-action-bucket="${key}" aria-pressed="${selected===key}">${e(name)} <span>${Number(count(key))}</span></button>`).join('')}</div>${items.length?items.slice(0,12).map(item=>{const rid=item.record_id||(selected==='overdue'||selected==='today'?null:item.id),shownWhen=selected==='pending_schedule'?item.proposal_remind_at:item.remind_at;return `<article class="work-action"><div class="work-action-body"><strong>${e(item.title||'客户跟进')}</strong><p>${e(item.customer_name||'未关联客户')}${shownWhen?` · ${e(formatDate(shownWhen,true))}`:''}${item.customer_id?` <button class="inline-link" data-customer="${Number(item.customer_id)}">客户档案</button>`:''}</p></div><div class="work-action-controls">${rid?`<button class="button small" data-record="${Number(rid)}">${selected==='needs_time'?'补时间':selected==='pending_schedule'?'核对安排':'查看跟进'}</button>`:''}${selected==='pending_schedule'&&item.proposal_id&&item.proposal_updated_at?`<button class="button primary small" data-confirm-proposal="${Number(item.proposal_id)}" data-proposal-updated-at="${e(item.proposal_updated_at)}">确认 ${e(`P${item.proposal_id}`)}</button>`:''}</div></article>`;}).join(''):empty('这一栏已经处理好了',selected==='overdue'?'没有逾期事项。可以看看今天要做的事。':selected==='needs_time'?'暂无等待补时间的跟进。':'这里的事项会自动更新。')}<button class="text-button" data-review-inbox>查看所有待确认 ${icon('arrow')}</button></section>`;
}
function workflowRouteHTML(){
  return `<details class="workflow-route"><summary>怎么走：记录 → 核对 → 安排 → 结果与下一步</summary><p>先保留交流原话，再决定哪些是事实、观察和待办。采纳为待办、确认档案变更、确认加入日程，是三个独立动作。</p><div class="workflow-links"><button class="button small" data-guide-entry="capture">1 · 记下交流</button><button class="button small" data-guide-entry="review">2 · 核对待办 / 档案</button><button class="button small" data-guide-entry="records">3 · 自己的待办补时间</button><button class="button small" data-guide-entry="agenda">4 · 日程记结果</button></div><p class="form-hint">等待客户或内部配合反馈的事项在客户工作台查看；截止、检查日期与自己的执行时间分别核对，不必为每条承诺补个人日程。</p><button class="text-button" data-usage-guide>查看完整使用指引与案例 ${icon('arrow')}</button></details>`;
}
function trainingEntry(scene){
  const targets={customer:scene.customer_id,visit:scene.visit_id,record:scene.record_id};
  const type=targets[scene.entry]?scene.entry:scene.visit_id?'visit':scene.record_id?'record':'customer';
  const id=Number(targets[type]);return Number.isSafeInteger(id)&&id>0?{type,id}:null;
}
function trainingScenariosHTML(){
  if(state.runtime.training!==true)return '';
  const scenarios=Array.isArray(state.runtime.training_scenarios)?state.runtime.training_scenarios:[];
  return `<section class="training-scenarios"><h3>独立离线演练</h3><p>这里使用独立示例数据，不发送真实提醒。可反复走案例，观察核对、确认和完成的变化。</p><div class="training-scenario-grid">${scenarios.map((scene,index)=>{const target=trainingEntry(scene);return `<article class="guide-case"><h4>${e(scene.title||'示例案例')}</h4><p>${e(scene.description||'按使用指引核对这条示例的原话与下一步。')}</p>${scene.customer_name?`<p class="form-hint">${e(scene.customer_name)}</p>`:''}${target?`<button class="button small" data-training-scenario="${index}">${{customer:'打开客户工作台',visit:'核对这次交流',record:'打开跟进事项'}[target.type]}</button>`:''}</article>`;}).join('')}</div>${scenarios.length?'':'<p class="form-hint">本轮暂无场景清单，可从上方入口记录一条示例。</p>'}</section>`;
}
function usageGuideHTML(){
  if(typeof flowGuideHTML==='function')return flowGuideHTML();
  const local=state.runtime.mode==='local';
  return dialogHeader('使用指引','从一次交流走到结果与下一步，可随时关闭并重新打开。','edit')+`<div class="dialog-body usage-guide"><div class="guide-intro"><strong>一条交流，走四步</strong><p>也可以直接说“帮我准备拜访／整理会后复盘／安排本周计划”。秘书先准备，你修改后确认。从记录、材料或客户交流点“核对秘书准备稿”，可以一次查看资料、人物与行动；旧待办点“整理推进反馈”核对结果。</p><div class="workflow-links"><button type="button" class="button small" data-secretary-progress="plan" data-period="week">准备本周计划</button></div><p>每一步都由你核对。采纳待办只建立跟进事项；确认档案变更才更新客户资料；确认安排才${local?'加入日程':'启用提醒'}。</p></div><ol class="guide-steps"><li><h3>1 · 记录：保留原话</h3><p>短交流用“随口记”。正式会议建“客户交流”，把录音文本和个人复盘分别保存。语音识别未配置时，可粘贴聆记文字，或用输入法语音输入后核对。</p><div class="workflow-links"><button class="button small" data-guide-entry="capture">随口记一条交流</button><button class="button small" data-guide-entry="visits">打开客户交流</button><button class="button small" data-guide-entry="audio">语音 / 粘贴转写</button></div></li><li><h3>2 · 核对：分清事实与下一步</h3><p>核对客户、项目、人物和原话依据；个人判断标作观察。需要推进的行动采纳为待办；客户资料变更另行确认，取消或稍后核对也会保留来源。</p><button class="button small" data-guide-entry="review">打开统一待核对</button></li><li><h3>3 · 安排：明确时间后再确认</h3><p>打开自己的待办，补具体时间、保存待确认安排，再核对并确认${local?'加入日程':'启用提醒'}。改期、取消也需要明确确认，确认前原安排仍有效。</p><p class="form-hint">客户或同事承诺先留在客户工作台等待反馈；截止、检查日期与自己的执行时间分开核对，不必给每条承诺排个人日程。${local?'本机模式到点请在后台查看。':''}</p><button class="button small" data-guide-entry="records">打开跟进事项，补时间</button></li><li><h3>4 · 完成：记结果，再走下一步</h3><p>待办选择“完成跟进并记结果”，保存实际结果，可顺手留下下一步。下一步没有时间时先成为待办。“仅完成日程”只结束本次安排，不记录跟进结果。</p><button class="button small" data-guide-entry="agenda">打开日程，处理本次跟进</button></li></ol><section class="guide-cases"><h3>三条案例路径</h3><p class="form-hint">这些是操作示例，按你自己的实际交流和记录走。</p><div class="guide-case-grid"><article class="guide-case"><h4>新线索 · 时间未定</h4><p>随口记客户需求与判断 → 分开核对事实 / 观察 → 采纳待办 → 时间未定先留跟进，明确后再确认安排。</p><button class="button small" data-guide-entry="capture">从随口记开始</button></article><article class="guide-case"><h4>正式会议 · 录音与复盘</h4><p>客户交流分别添加录音文本和我的复盘 → 对照来源核对承诺 → 采纳待办、单独确认档案 → 在客户工作台看项目与等待反馈。</p><button class="button small" data-guide-entry="visits">从客户交流开始</button></article><article class="guide-case"><h4>逾期推进 · 结果与下一步</h4><p>工作台查看逾期 → 打开原待办 → 记录实际结果 → 保存无时间下一步；如果只是计划变动，核对改期或取消原安排。</p><button class="button small" data-guide-entry="dashboard">查看工作台待处理</button></article></div></section>${trainingScenariosHTML()}<div class="guide-close"><button class="button" data-close="edit">关闭指引</button></div></div>`;
}
