  if(project?.options&&!Array.from(project.options).some(option=>String(option.value)===String(result.opportunity_id||'')))return null;
  if(!saving&&focus!==undefined&&focus!==null&&focus!==form.dataset.discussionFocus)return null;
  if(!saving&&focus===null&&(state.discussionContext?.source_record_id||state.discussionContext?.contact_id||state.discussionContext?.timeline_enabled))return null;
