    `<div class="filter-bar"><div class="filter-search">${icon('search')}<input id="customer-filter-q" data-search-filter type="search" aria-label="搜索客户" placeholder="搜索客户、联系人或电话" value="${e(state.q)}"></div><select data-filter="stage" aria-label="销售阶段">${stageOptions(state.stage,true)}</select><span class="result-label">${Number(data.total??data.items?.length??0)} 个单位</span></div>`+
    `<section class="panel">${data.items?.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>客户 / 联系人</th><th class="table-hide-mobile">联系电话</th><th>销售阶段</th><th>历史客户金额</th><th class="table-hide-tablet">关联记录</th><th></th></tr></thead><tbody>${data.items.map(c=>`<tr data-customer="${Number(c.id)}" tabindex="0" aria-label="查看客户：${e(c.name)}"><td class="table-customer-name"><div class="table-primary"><span class="customer-initial">${e(c.name?.slice(0,1)||'客')}</span><div><span class="table-title">${e(c.name)}</span><span class="table-sub">${e((c.primary_contact_name??c.contact)||'尚未补充联系人')}</span></div></div></td><td class="table-hide-mobile">${e((c.primary_contact_phone??c.phone)||'—')}</td><td class="table-customer-stage">${badge(stages[c.stage]||c.stage,c.stage)}</td><td class="table-money"><span class="mobile-card-label">历史客户金额</span>${e(customerMoney(c))}</td><td class="table-hide-tablet table-time">${Number(c.record_count||0)} 条</td><td class="table-arrow">${icon('right')}</td></tr>`).join('')}</tbody></table></div>${pagination(data)}`:empty(state.q?'没有匹配的单位':'从一个单位开始',state.q?'换个名称、简称或联系人试试；同单位的另一位客户请直接添加联系人。':'先建单位，再添加多位客户联系人和独立项目。','<button class="button small" data-new-customer>添加客户</button>')}</section>`;
