function scheduleCompletionActions(task,record=null){
  if(task?.status!=='pending')return '';
  const rid=Number(record?.id??task.record_id),kind=record?.kind??task.record_kind,status=record?.status??task.record_status;
  const canRecordResult=Number.isSafeInteger(rid)&&rid>0&&kind==='action'&&['unfiled','following'].includes(status);
  return `${canRecordResult?`<button class="button primary small" data-complete-outcome="${rid}" aria-label="完成跟进并记结果：${e(task.title)}">完成跟进并记结果</button>`:''}<button class="button small" data-complete-task="${Number(task.id)}" aria-label="仅完成日程：${e(task.title)}，不记录跟进结果">仅完成日程</button>`;
}
function agendaDateGroups(items,plans,start=0){
  const groups=new Map(),put=(date,entry)=>{if(!groups.has(date))groups.set(date,[]);groups.get(date).push(entry);};
  for(const task of items){const at=Math.max(Number(task.remind_at),start||Number(task.remind_at)),p=shanghaiParts(at);put(`${p.year}-${p.month}-${p.day}`,{kind:'task',value:task,at});}
  for(const plan of plans){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(plan.date||'')))continue;put(plan.date,{kind:'plan',value:plan,at:plan.start_at?Number(plan.start_at):Infinity});}
  return [...groups.entries()].sort(([a],[b])=>a.localeCompare(b)).map(([date,entries])=>[date,entries.sort((a,b)=>a.at-b.at||(a.kind===b.kind?Number(a.value.id)-Number(b.value.id):a.kind==='task'?-1:1))]);
}
function agendaMoreHTML(title,actions){return actions?`<details class="agenda-more" data-agenda-more><summary class="button small" aria-label="更多操作：${e(title)}">更多 ${icon('right')}</summary><div class="agenda-more-menu">${actions}</div></details>`:'';}
function agendaTaskHTML(task,start,end){
  const taskEnd=Number(task.remind_at)+Number(task.duration_minutes||30)*60,continued=start&&Number(task.remind_at)<start,continuesAfter=end&&taskEnd>end,closed=['completed','cancelled'].includes(task.status);
  const recordId=Number(task.record_id||0),canResult=!closed&&recordId&&task.record_kind==='action'&&['unfiled','following'].includes(task.record_status||task.linked_record_status||'');
  const status=task.status==='completed'?'日程已完成':task.status==='cancelled'?'已取消':taskEnd<Date.now()/1000?'待反馈':'已安排',statusClass=closed?task.status:status==='待反馈'?'attention':'confirmed';
  const project=task.opportunity_name||'',meta=[task.customer_name,project&&!task.project_link_stale?`项目：${project}${task.opportunity_archived?'（已归档）':''}`:task.project_link_stale?'项目归属待核对':'',`预计 ${task.duration_minutes||30} 分钟`].filter(Boolean);
  const view=recordId?`<button type="button" class="button small" data-record="${recordId}">${closed?'查看记录':'查看 / 改期'}</button>`:'';
  const result=canResult?`<button type="button" class="button primary small" data-complete-outcome="${recordId}" aria-label="完成跟进并记结果：${e(task.title)}">记跟进结果</button>`:'';
  const more=(!closed?`<button type="button" class="button small" data-complete-task="${Number(task.id)}" aria-label="仅完成日程：${e(task.title)}，不记录跟进结果">仅完成日程</button>`:'')+(recordId?`<button type="button" class="button small" data-next-visit="${recordId}">安排下一次</button>`:'');
  return `<article class="agenda-item agenda-item-task ${e(task.status)}" data-agenda-task="${Number(task.id)}"><div class="agenda-time"><time datetime="${e(new Date(Number(continued?start:task.remind_at)*1000).toISOString())}">${e(clock(continued?start:task.remind_at))}</time>${continued?'<small>跨时段继续</small>':''}</div><div class="agenda-item-body"><div class="agenda-item-heading">${recordId?`<button type="button" class="agenda-title" data-record="${recordId}">${e(task.title)}</button>`:`<strong class="agenda-title">${e(task.title)}</strong>`}<span class="agenda-state ${e(statusClass)}">${e(status)}</span></div><p class="agenda-item-meta">${meta.map(e).join(' · ')}</p>${continued||continuesAfter?`<details class="agenda-span"><summary>${continued?'跨时段继续':'延续至下个时段'} · 查看完整时间</summary><p>原安排 ${e(formatDate(task.remind_at,true))} — ${e(formatDate(taskEnd,true))}。本窗占用 ${e(formatDate(Math.max(start||task.remind_at,task.remind_at),true))} — ${e(formatDate(Math.min(end||taskEnd,taskEnd),true))}。</p></details>`:''}${typeof matterContextHTML==='function'?matterContextHTML(task.matters||[]):''}<div class="agenda-item-actions">${result}${view}${agendaMoreHTML(task.title,more)}</div></div></article>`;
}
function agendaPlanHTML(plan){
  const status=plan.status==='needs_attention'?'需核对':plan.start_at?'待确认':'待约',meta=[plan.customer_name,plan.opportunity_name?`项目：${plan.opportunity_name}`:''].filter(Boolean);
  const more=typeof lifecycleActions==='function'?lifecycleActions(plan.record_id):'';
  return `<article class="agenda-item agenda-item-plan" data-agenda-plan="${Number(plan.id)}"><div class="agenda-time ${plan.start_at?'':'undecided'}">${plan.start_at?`<time datetime="${e(new Date(Number(plan.start_at)*1000).toISOString())}">${e(clock(plan.start_at))}</time>`:'<span>时间待定</span>'}</div><div class="agenda-item-body"><div class="agenda-item-heading"><button type="button" class="agenda-title" data-flow-plan="${Number(plan.id)}">${e(plan.title)}</button><span class="agenda-state attention">${e(status)}</span></div>${meta.length?`<p class="agenda-item-meta">${meta.map(e).join(' · ')}</p>`:''}${plan.goal?`<p class="agenda-item-goal"><span>目标</span> ${e(plan.goal)}</p>`:''}${typeof matterContextHTML==='function'?matterContextHTML(plan.matters||[]):''}<div class="agenda-item-actions"><button type="button" class="button small" data-flow-plan="${Number(plan.id)}">${plan.status==='needs_attention'?'核对安排':'完善安排'}</button>${agendaMoreHTML(plan.title,more)}</div></div></article>`;
}
function agendaBoardHTML(data,items){
  const plans=data.secretary_plans||[],groups=agendaDateGroups(items,plans,Number(data.start||0)),today=shanghaiParts(Date.now()/1000),todayKey=`${today.year}-${today.month}-${today.day}`;
  const counts=[['已安排',items.filter(t=>!['completed','cancelled'].includes(t.status)).length,'confirmed'],['待约 / 待确认',plans.length,'attention'],['日程已完成',items.filter(t=>t.status==='completed').length,'completed'],['已取消',items.filter(t=>t.status==='cancelled').length,'cancelled']];
  return `<section class="panel agenda-board"><div class="agenda-board-head"><div><h2>${{day:'当日日程',week:'本周日程',month:'本月日程'}[state.period]||'日程'}</h2><p>${e(data.start?shortDate(data.start):state.date)}${state.period!=='day'&&data.end?` — ${e(shortDate(data.end-1))}`:''}</p></div><div class="agenda-counts" aria-label="本时段事项数量">${counts.filter(([,n])=>n).map(([label,n,kind])=>`<span class="agenda-state ${kind}">${e(label)} <strong>${n}</strong></span>`).join('')||'<span class="agenda-item-meta">暂无事项</span>'}</div></div>${groups.length?groups.map(([date,entries])=>`<section class="agenda-date-group" data-agenda-date="${e(date)}"><div class="agenda-date-heading"><h3><time datetime="${e(date)}">${e(new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'short'}).format(new Date(`${date}T12:00:00+08:00`)))}</time></h3>${date===todayKey?'<span class="agenda-today">今天</span>':''}<span class="agenda-date-count">${entries.length} 项</span></div>${entries.map(entry=>entry.kind==='task'?agendaTaskHTML(entry.value,Number(data.start||0),Number(data.end||0)):agendaPlanHTML(entry.value)).join('')}</section>`).join(''):empty('这段时间还没有日程或待约计划','可以先告诉秘书日期和要做的事，钟点以后再补。','<button type="button" class="button small" data-go="dashboard">告诉秘书一件事</button>')}</section>`;
}
