  if(record.task_status==='completed'&&record.status!=='done')return '本次日程已结束 · 行动仍需跟进';
  if(record.task_status==='pending'&&record.remind_at)return `${waiting?'检查反馈':'已确认日程'}：${formatDate(record.remind_at,true)}`;
  if(record.proposal_status==='pending'&&record.proposal_remind_at)return `待确认安排：${formatDate(record.proposal_remind_at,true)}`;
  const check=terms.check_at?`检查反馈：${formatDate(terms.check_at,true)} · 尚未启用提醒`:terms.check_date?`检查反馈：${terms.check_date} · 具体时间未定`:'检查时间未定';
