function analysisSection(record,analysis,{capture=null,nature=null}={}){
  const processing=['queued','processing'].includes(capture?.status),reflection=nature==='reflection';
  const adoptedRecord=action=>action.adopted_record_id||action.record_id;
  const actionCard=action=>`<div class="analysis-action"><div class="analysis-action-title">${e(action.title)}</div>${sourceActionNotice(action)}${action.reason?`<p>${e(action.reason)}</p>`:''}<div class="analysis-action-meta">${action.owner_hint?`<span>负责 / 配合：${e(action.owner_hint)}</span>`:''}<span>${action.remind_at?`提及时间：${e(formatDate(action.remind_at,true))}`:['customer','team'].includes(action.action_terms?.executor_kind||action.executor_kind)?({customer:'等待客户反馈',team:'等待内部反馈'}[action.action_terms?.executor_kind||action.executor_kind]+'；截止 / 检查另行核对'):'时间待补充'}</span></div>${adoptedRecord(action)?`<button class="text-button" data-record="${Number(adoptedRecord(action))}">查看跟进 ${icon('arrow')}</button>`:sourceActionPaused(action)?sourceActionRecovery(action):`<button class="button small" data-adopt-action="${Number(action.id)}" data-id="${Number(record.id)}" data-visit-revision="${e(action.visit_revision||'')}" ${processing||analysis?.stale||action.blocked?'disabled title="来源需要先核对"':''}>${icon('plus')} 加入跟进</button>`}</div>`;
  const actions=Array.isArray(analysis?.actions)?analysis.actions:[],commitments=actions.filter(action=>action.kind==='commitment'),suggestions=actions.filter(action=>action.kind!=='commitment'),previous=analysis?.previous_actions||[];
  return `<section class="analysis-section"><div class="analysis-heading"><div><span class="section-overline">${reflection?'我的思考 → 下一步':'本次交流 → 下一步'}</span><h3>${reflection?'整理我的思考':'本次交流整理'}</h3></div><button class="button small ${analysis?'':'primary'}" data-organize-record="${Number(record.id)}" ${processing?'disabled':''}>${icon('leaf')} ${processing?'后台整理中…':analysis?'重新整理':'帮我整理'}</button></div><p class="analysis-intro">${reflection?'整理个人判断和可核实的下一步，不将思考当客户承诺。':'提炼这次交流重点与下一步。'}整理结果需你核对；重新整理会保留已采纳待办的历史，新待办重新核对后采纳。</p>${record.customer_id?`<button class="text-button analysis-coaching-link" data-show-coaching="${Number(record.customer_id)}">看这位客户的推进建议 ${icon('arrow')}</button>`:''}${processing?'<p class="analysis-warning">已按确认归属在后台重新整理，完成后可采纳。</p>':analysis?.stale?'<p class="analysis-warning">记录已有修改，以下是旧整理。请先重新整理，再采纳待办。</p>':''}${analysis?`<div class="analysis-block"><h4>${reflection?'思考中的行动候选':'明确待办'} <span>${commitments.length}</span></h4>${commitments.length?commitments.map(actionCard).join(''):`<p class="analysis-empty">${reflection?'暂未提取到可核对的行动。':'暂未提取到明确承诺。'}</p>`}</div><div class="analysis-block"><h4>建议跟进 <span>${suggestions.length}</span></h4>${suggestions.length?suggestions.map(actionCard).join(''):'<p class="analysis-empty">暂无额外建议。</p>'}</div><details class="review-disclosure"><summary>${reflection?'思考摘要与待核实问题':'交流摘要与待核实问题'}${analysis.open_questions?.length?` · ${analysis.open_questions.length} 项待核实`:''}</summary>${analysis.summary?`<div class="analysis-summary">${e(analysis.summary)}</div>`:''}${analysis.key_points?.length?`<div class="analysis-block"><h4>${reflection?'思考要点':'沟通要点'}</h4><ul>${analysis.key_points.map(point=>`<li>${e(point)}</li>`).join('')}</ul></div>`:''}${analysis.open_questions?.length?`<div class="analysis-block questions"><h4>还需要弄清楚</h4><ul>${analysis.open_questions.map(point=>`<li>${e(point)}</li>`).join('')}</ul></div>`:''}</details>${previous.length?`<details class="profile-group"><summary>以前采纳的待办 <span>${previous.length}</span></summary><div class="profile-group-body">${previous.map(item=>`<p><button class="inline-link" data-record="${Number(item.record_id)}">${e(item.title)}</button> ${badge(item.superseded_by_analysis_version?'被新版整理替代':statuses[item.status]||item.status,item.status)}</p>`).join('')}</div></details>`:''}`:`<div class="analysis-placeholder">${reflection?'整理后，选择需要核实的判断或可执行的建议，再决定是否采纳为待办。':'整理后，客户需求、约定和需要核实的事可以逐项跟进。'}</div>`}</section>`;
}
function transcriptComparison(data){const transcript=data.transcript;if(!transcript?.original_text)return '';return `<details class="detail-section transcript-reference"><summary>转写对照 · 原始文字与人工修正</summary><h3>1 · 原始转写</h3><div class="original-note">${e(transcript.original_text)}</div><h3>2 · 人工核对后的文字</h3><div class="detail-text">${e(transcript.corrected_text||'尚未保存修正文字')}</div><p class="form-hint">原始转写单独保留；整理结果需要另外核对人物、责任人、金额与日期。</p></details>`;}
function actionTermsHTML(action){const terms=action.action_terms||action,executor=terms.executor_kind||'unknown';return `<div class="action-terms"><p>${badge({self:'我的行动',customer:'等待客户反馈',team:'内部配合 · 等待反馈',unknown:'责任人待核对'}[executor]||'责任人待核对',executor==='unknown'?'pending':'reported')}</p>${terms.execution_at?`<p>执行预约：${e(materialDate(terms.execution_at))}</p>`:''}${terms.deadline_at||terms.deadline_date?`<p>截止：${e(terms.deadline_at?materialDate(terms.deadline_at):terms.deadline_date)}</p>`:''}${terms.check_at||terms.check_date?`<p>检查 / 核实：${e(terms.check_at?materialDate(terms.check_at):terms.check_date)}</p>`:''}${terms.duration_minutes?`<p>预计用时：${Number(terms.duration_minutes)} 分钟${terms.duration_evidence?' · 依据：'+e(terms.duration_evidence):' · 以核对内容为准'}</p>`:''}</div>`;}
function actionOriginsHTML(data){
  const pack=data.action_origins||{},items=pack.items||[];if(!items.length)return '';
  return `<section class="detail-section action-origins"><h3>这一步从哪里来</h3><p class="form-hint">原交流、本人输入和 AI 建议分别保留；采用后的行动可在下方继续跟进。</p>${items.map(origin=>{
    if(origin.type==='record')return `<article class="review-card"><strong>原记录：${e(origin.title)}</strong><button type="button" class="button small" data-record="${Number(origin.record_id)}">回看原记录</button></article>`;
    const fields=(origin.scope_changed_fields||[]).filter(field=>['customer','project','contacts'].includes(field)),labels={customer:'单位',project:'项目',contacts:'相关人物'};
    const changed=origin.scope_status==='changed'?`<p class="analysis-warning">这项行动的${e(fields.length?fields.map(field=>labels[field]).join('、'):'归属')}后来有变化，原上下文仅供回看，请按当前资料核对。</p>`:origin.scope_status==='unknown'?'<p class="form-hint">部分历史归属未保留，无法判断是否变化；原上下文供回看，以当前资料为准。</p>':!origin.scope_status&&origin.same_customer===false?'<p class="analysis-warning">这项行动的单位归属后来有变化，原上下文仅供回看，请按当前资料核对。</p>':'';
    const review=origin.scope_needs_review?'<p class="analysis-warning">当前归属或来源需要重新核对；这不代表已经移到其他对象。</p>':'',when=origin.adopted_at?`<p class="form-hint">采用于 ${e(formatDate(origin.adopted_at,true))}</p>`:'';
    if(origin.type==='discussion')return `<article class="review-card"><strong>来自 AI 跟进讨论：${e(origin.title)}</strong>${changed}${review}${when}<details class="review-disclosure"><summary>我的原问题与当时的 AI 回复</summary><h4>我的原问题</h4><p class="source-text">${e(origin.user_text)}</p><h4>当时的 AI 回复（建议）</h4><p class="source-text">${e(origin.answer_text)}</p></details><button type="button" class="button small" data-origin-discussion="${Number(origin.thread_id)}" data-origin-message="${Number(origin.message_id)}">回到原讨论与建议</button></article>`;
    const options={...origin.scope,kind:origin.kind,run_id:origin.run_id,period:origin.period,start_date:origin.start_date};return `<article class="review-card"><strong>来自${e({visit_prepare:'会前准备',recap:'会后复盘',followup_result:'跟进结果',plan:'推进计划'}[origin.kind]||'秘书准备稿')}</strong>${changed}${review}${when}<details class="review-disclosure"><summary>回看我的完整输入</summary><p class="source-text">${e(origin.text)}</p></details><button type="button" class="button small" data-origin-progress="${e(JSON.stringify(options))}">回看原准备稿与采用结果</button></article>`;
  }).join('')}${pack.truncated?'<p class="form-hint">这里只列最近 10 份来源，可通过原讨论或准备稿继续回看历史。</p>':''}</section>`;
}
