  const detailsPanel=`${typeof accountResearchEntryHTML==='function'?accountResearchEntryHTML(data.accountContext,c.id):''}<section class="profile-section customer-basic-summary"><div class="profile-section-head"><div><h3>基本资料</h3><p>客户阶段、历史金额和备注；交易金额按项目核对。</p></div><button class="button" data-edit-customer="${Number(c.id)}">${icon('edit')} 编辑基本资料</button></div><p>${badge(stages[c.stage]||c.stage,c.stage)} <span>历史客户金额 ${e(customerMoney(c))}</span></p>${c.notes?`<div class="detail-text">${e(c.notes)}</div>`:''}</section>${drafts.length?`<section class="profile-pending"><h3>${icon('inbox')} ${drafts.length} 份客户变更待确认</h3>${drafts.map(d=>draftSummary(d)).join('')}</section>`:''}<section class="profile-section"><div class="profile-section-head"><div><h3>客户画像</h3><p>已核实资料按需查看，画像候选在下方逐项核对。</p></div><button class="button" data-add-fact="${Number(c.id)}">${icon('plus')} 补充画像</button></div>${groupHTML}</section>${typeof accountKnowledgeHTML==='function'?accountKnowledgeHTML(data.accountContext,c.id):''}<details class="review-disclosure"><summary>拜访简报与客户画像概览</summary>${visitBrief(profile,coaching)}</details><details class="profile-group"><summary><span>画像修改历史</span><span class="profile-count">最近 ${Math.min(30,profile.history?.length||0)} 条</span>${icon('right')}</summary><div class="profile-group-body">${history?`<ol class="timeline profile-history">${history}</ol>`:'<p class="profile-empty">后续补充会保留依据和时间，方便回看。</p>'}</div></details>`;
