function visitSourceTimeHTML(visit,role){
  return `<details class="review-disclosure source-time-editor" ${role==='supplement'?'open':''}><summary>这份来源描述的实际发生时间</summary><label for="visit-source-time-basis">时间依据</label><select id="visit-source-time-basis" name="time_basis"><option value="visit" ${role!=='supplement'?'selected':''}>描述原交流，沿用交流时间</option><option value="own" ${role==='supplement'?'selected':''}>后来的进展，单独保留发生时间</option></select><label for="visit-source-occurred-at">单独发生时间（北京时间，未知可留空）</label><input id="visit-source-occurred-at" name="occurred_at" type="datetime-local" ${role!=='supplement'?'disabled':''}><p class="form-hint">原交流：${visit.occurred_at?e(materialDate(visit.occurred_at)):'实际时间未核实'}。后来发生的电话、邮件或补充可选择单独保留时间；留空表示未知，不会填成原交流日期。“下周”等相对时间需先核实。</p></details>`;
}
function materialTimeDifferenceHTML(){return '<label class="source-time-confirm"><input type="checkbox" name="confirm_time_difference"> 我确认材料属于所选交流，保留材料自己的实际时间</label><p class="form-hint">材料与交流的发生时间不同时勾选；只确认来源关联，不会改写原交流日期。</p>';}
async function loadCustomerSchema(){if(!state.customerSchema){const data=await api('/api/customer-schema');const normalize=fields=>Array.isArray(fields)?Object.fromEntries(fields.map(field=>[field.key,field])):(fields||{});state.customerSchema={account_fields:normalize(data.account_fields),contact_fields:normalize(data.contact_fields)};}return state.customerSchema;}
function basisLabel(basis,source){return basis==='observation'?(source?.type==='public'?'公开观察':'个人观察'):'明确信息';}
function fieldLabel(key){return state.customerSchema?.account_fields?.[key]?.label||state.customerSchema?.contact_fields?.[key]?.label||key;}
function profileFactSourceHTML(f){
  const source=f.source||{};if(source.type!=='public')return f.source_record_id?`<button class="inline-link" data-record="${Number(f.source_record_id)}">回看原始记录</button>`:'';
  let link='';try{const url=new URL(source.url);if(['https:','http:'].includes(url.protocol)&&!url.username&&!url.password)link=`<a class="inline-link" href="${e(url.href)}" target="_blank" rel="noopener noreferrer">查看公开原文 ↗</a>`;}catch{}
  return `<div class="profile-fact-source"><p class="form-hint">公开出处：${e(source.title||source.url||'公开资料')} · 发布日期：${e(source.published_at||'未提供')} · 获取时间：${e(source.fetched_at?formatDate(source.fetched_at,true):'未提供')}</p>${link}</div>`;
}
function profileFactEditSourceHTML(f){return f?.source?.type==='public'?`<div class="profile-fact-edit-source"><p class="form-hint">原公开资料供你对照。修改内容时请一起核对本次依据；新内容按本次选择的信息性质保存，原出处保留在旧值与来源中。</p>${profileFactSourceHTML(f)}</div>`:'';}
function factCard(f,customerId,contactId=null,history=[]){
  const previous=history.filter(item=>item.key===f.key&&Number(item.contact_id||0)===Number(contactId||0)&&Number(item.id)!==Number(f.id));
  const oldPublic=previous.some(item=>item.source?.type==='public'),manual=(!f.source||f.source.type==='manual')&&!f.source_record_id;
  const prior=previous.length?`<details class="profile-fact-history"><summary>这项资料的旧值与来源 · ${previous.length} 条</summary><p class="form-hint">旧资料按当时的依据保留；本次修订按当前的信息性质使用。</p>${previous.map(item=>`<article><p><strong>${e(item.value)}</strong></p><p class="form-hint">${e(basisLabel(item.basis,item.source))} · ${e(formatDate(item.updated_at,true))}</p>${profileFactSourceHTML(item)}${item.evidence?`<blockquote>${e(item.evidence)}</blockquote>`:''}</article>`).join('')}</details>`:'';
  return `<div class="profile-fact" data-fact-key="${e(f.key)}" data-fact-contact="${Number(contactId||0)}"><div class="profile-fact-heading"><strong>${e(f.label||fieldLabel(f.key))}</strong><button class="text-button" data-add-fact="${Number(customerId)}" data-field="${e(f.key)}" ${contactId?`data-contact-id="${Number(contactId)}"`:''} aria-label="更新${e(f.label||fieldLabel(f.key))}">更新</button></div><p>${e(f.value)}</p><div class="fact-meta">${badge(basisLabel(f.basis,f.source),f.basis==='observation'?'observation':'reported')}<time>${e(formatDate(f.updated_at))}</time>${f.source_record_id?`<button class="inline-link" data-record="${Number(f.source_record_id)}">原始记录</button>`:f.source?.type==='public'?'<span>公开来源</span>':'<span>手动补充</span>'}</div>${profileFactSourceHTML(f)}${f.evidence?`<blockquote>${e(f.evidence)}</blockquote>`:''}${manual&&oldPublic?'<p class="form-hint">当前内容是手工修订，原公开出处可在下方回看。</p>':''}${prior}</div>`;
}
function coachingOverview(data){
  const items=Array.isArray(data.items)?data.items:[];
  return `<section class="panel coaching-overview"><div class="panel-head"><div><span class="section-overline">把交流接成下一步</span><h2>客户推进建议 ${badge('AI 建议','ai-suggestion')}</h2><p>${data.generating?'秘书正在结合新的交流梳理建议…':'围绕当前卡点，想清楚接下来找谁、问什么、做什么。'}</p></div><button class="text-button" data-go="customers">客户 ${icon('arrow')}</button></div>${items.length?`<div class="coaching-overview-list">${items.slice(0,5).map(item=>`<button class="coaching-overview-item" data-show-coaching="${Number(item.customer_id)}"><span class="customer-initial">${e(item.customer_name?.slice(0,1)||'客')}</span><span class="coaching-overview-body"><strong>${e(item.customer_name)}</strong><span>${e(item.objective||item.summary)}</span></span>${item.stale?badge('资料有更新','pending'):''}${icon('right')}</button>`).join('')}</div>`:`<p class="coaching-light-empty">${e(data.error?'推进建议暂时未能加载，稍后会自动重试。':data.generating?'正在思考推进方向，完成后会出现在这里。':'记下一次客户交流，秘书会在整理后接着思考推进方向；也可进入客户档案随时生成。')}</p>`}</section>`;
}
function coachingFeedbackHTML(data){
  const items=data.feedback_history||[];if(!items.length)return '';
  const labels={completed:'已落实',blocked:'遇阻',paused:'暂缓',not_applicable:'不适用'},latest=items[0];
  return `<section class="coaching-feedback-receipt"><p><strong>最近反馈 · ${e(labels[latest.status]||'已保存')}</strong> · ${e(formatDate(latest.updated_at,true))}</p><p>${e(latest.title)}${latest.note?`：${e(latest.note)}`:''}</p><details class="review-disclosure"><summary>推进反馈历史 · 最近 ${items.length} 条</summary>${items.map(item=>`<article class="review-card"><p>${e(formatDate(item.updated_at,true))} · ${e(labels[item.status]||'已保存')} · 第 ${Number(item.version)} 轮建议</p><p>${e(item.title)}${item.note?`：${e(item.note)}`:''}</p></article>`).join('')}</details><p class="form-hint">反馈已保留为下一轮思考的依据。需要结束跟进或调整日程时，请打开原事项处理。</p></section>`;
}
function coachingSection(customerId,data){
  const recommendation=data.recommendation,generating=Boolean(data.generating),stale=Boolean(recommendation?.stale);
  const actionCard=(action,index)=>`<article class="coaching-action ${index===0?'coaching-first':''}"><div class="coaching-action-heading"><span>${index+1}</span><h4>${e(action.title)}</h4>${index===0?badge('建议优先','primary-contact'):''}</div>${action.reason?`<p class="coaching-action-reason"><strong>为什么做</strong>${e(action.reason)}</p>`:''}<details class="coaching-action-details"><summary>找谁、怎么准备、怎么开口 ${icon('right')}</summary><dl>${[['contact_hint','建议找谁'],['preparation','准备材料'],['talk_track','可以这样问'],['success_signal','怎样算有进展']].filter(([key])=>action[key]).map(([key,label])=>`<div><dt>${label}</dt><dd>${e(action[key])}</dd></div>`).join('')}</dl></details><div class="coaching-action-footer">${action.adopted_record_id?`<button class="text-button" data-record="${Number(action.adopted_record_id)}">${icon('check')} 已加入跟进 · 查看</button>`:`<button class="button small" data-adopt-coaching="${index+1}" data-coaching-customer-id="${Number(customerId)}" data-coaching-version="${e(recommendation.version)}" ${stale||generating?'disabled':''}>${icon('plus')} 采纳为跟进事项</button>`}<button class="button small" data-coach-feedback="${index+1}" data-feedback-customer="${Number(customerId)}" data-feedback-version="${Number(recommendation.version)}">反馈推进结果</button>${action.feedback?.status||action.feedback_status?badge({completed:'已落实',blocked:'受阻',paused:'暂缓',not_applicable:'不适用'}[action.feedback?.status||action.feedback_status]||'已反馈','reported'):''}</div></article>`;
  return `${coachingFeedbackHTML(data)}<div class="coaching-section-head"><div><span class="section-overline">秘书帮你多想一步</span><h3>推进建议 ${badge('AI 建议','ai-suggestion')}</h3></div><button class="button small ${recommendation?'':'primary'}" data-generate-coaching="${Number(customerId)}" ${generating?'disabled':''}>${icon('leaf')} ${generating?'正在思考…':recommendation?'重新思考':'帮我想下一步'}</button></div><p class="coaching-intro">结合已记录的需求、联系人与交流推演。历史信息和个人观察仍需核实；采纳只加入跟进，时间由你安排。</p>${data.error?`<p class="analysis-warning" role="alert">${e(data.error)}</p>`:''}${stale?'<p class="analysis-warning">客户资料或交流已有更新，下面的建议基于旧信息。请重新思考后再采纳。</p>':''}${generating?'<p class="coaching-generating" role="status"><span class="refresh-dot"></span>正在梳理推进方向，完成后会自动更新。你可以继续查看客户资料。</p>':''}${recommendation?`<div class="coaching-objective"><span>本轮建议目标</span><h4>${e(recommendation.objective)}</h4>${recommendation.summary?`<p>${e(recommendation.summary)}</p>`:''}</div>${recommendation.rationale?`<div class="coaching-rationale"><h4>为什么优先推进这一步</h4><p>${e(recommendation.rationale)}</p></div>`:''}<div class="coaching-actions">${(recommendation.next_moves||[]).slice(0,3).map(actionCard).join('')}</div>${recommendation.questions?.length?`<div class="coaching-questions"><h4>${icon('chat')} 下次交流值得问清楚</h4><ul>${recommendation.questions.map(question=>`<li>${e(question)}</li>`).join('')}</ul></div>`:''}${recommendation.risks?.length?`<details class="coaching-risks"><summary>推进时留意 <span>${recommendation.risks.length} 项</span>${icon('right')}</summary><ul>${recommendation.risks.map(risk=>`<li>${e(risk)}</li>`).join('')}</ul></details>`:''}${recommendation.sources?.length?`<div class="coaching-sources"><h4>建议依据的交流记录</h4>${recommendation.sources.map(item=>`<button class="inline-link" data-record="${Number(item.record_id)}">${e(item.title||'查看交流记录')}</button>`).join('')}</div>`:''}<p class="coaching-meta">${e(formatDate(recommendation.created_at))} 生成 · 可调整的推进思路，需结合现场判断</p>`:!generating?'<div class="coaching-empty"><span>'+icon('leaf')+'</span><p>先说出你知道的，资料不用一次填齐。<br>秘书会帮你找出值得推进的一步，以及下次需要问清楚的问题。</p></div>':''}<p id="coaching-sync-message" class="form-hint" role="status"></p>`;
}
function scheduleCoachingPoll(customerId,delay=15000){
  clearTimeout(coachingPollTimer);
  coachingPollTimer=setTimeout(async()=>{
    if(!state.authenticated||!$('#detail-dialog').open||state.detail?.type!=='customer'||Number(state.detail.id)!==Number(customerId))return;
    if(document.hidden||$('#edit-dialog').open||state.coachingBusy){scheduleCoachingPoll(customerId);return;}
    try{const data=await api(`/api/customers/${customerId}/coaching`);if(state.detail?.type!=='customer'||Number(state.detail.id)!==Number(customerId))return;const section=$('#customer-coaching');if(!section)return;const previous=JSON.stringify(state.detail.data.coaching);state.detail.data.coaching=data;if(previous!==JSON.stringify(data)){const expanded=$$('.coaching-action-details',section).map(detail=>detail.open);const riskOpen=$('.coaching-risks',section)?.open;section.innerHTML=coachingSection(customerId,data);$$('.coaching-action-details',section).forEach((detail,index)=>{detail.open=Boolean(expanded[index]);});if(riskOpen&&$('.coaching-risks',section))$('.coaching-risks',section).open=true;}else if($('#coaching-sync-message'))$('#coaching-sync-message').textContent='';scheduleCoachingPoll(customerId,data.generating?5000:15000);}catch{if($('#coaching-sync-message'))$('#coaching-sync-message').textContent='建议同步暂时中断，稍后自动重试。';scheduleCoachingPoll(customerId);}
  },delay);
}
async function refreshCoaching(customerId){const data=await api(`/api/customers/${customerId}/coaching`);if(state.detail?.type==='customer'&&Number(state.detail.id)===Number(customerId)&&$('#customer-coaching')){state.detail.data.coaching=data;$('#customer-coaching').innerHTML=coachingSection(customerId,data);scheduleCoachingPoll(customerId,data.generating?5000:15000);}return data;}

function openCoachFeedback(customerId,version,index){
  const recommendation=state.detail?.type==='customer'&&Number(state.detail.id)===Number(customerId)?state.detail.data.coaching?.recommendation:null;const move=Number(recommendation?.version)===Number(version)?recommendation.next_moves?.[Number(index)-1]:null;
  openDialog('edit',dialogHeader('反馈推进结果','告诉秘书这一步的实际结果，后续建议会据此调整。','edit')+`<div class="dialog-body"><form id="coach-feedback-form" data-customer-id="${Number(customerId)}" data-version="${Number(version)}" data-action-index="${Number(index)}"><div class="form-field"><label for="coach-feedback-status">目前进展</label><select id="coach-feedback-status" name="status" required><option value="">请选择实际结果</option><option value="completed">已经落实</option><option value="blocked">遇到阻力，需要换个思路</option><option value="paused">暂缓推进</option><option value="not_applicable">不适合当前客户</option></select></div><div class="form-field"><label for="coach-feedback-note">原因 / 客户反馈（选填）</label><textarea id="coach-feedback-note" name="note" maxlength="1000" placeholder="例如：客户已有同类设备，下一步要讨论兼容与替换成本。"></textarea></div><p class="form-hint">“已经落实”会同时完成已采纳待办，并停止其提醒。受阻、暂缓、不适用只反馈进展，已确认提醒仍有效；改期或取消请进入对应待办。</p>${move?.adopted_record_id?`<button type="button" class="inline-link" data-record="${Number(move.adopted_record_id)}">打开已采纳待办，改期 / 取消提醒</button>`:''}<p class="form-error" role="alert"></p><div class="form-footer"><button type="button" class="button" data-close="edit">关闭</button><button type="submit" class="button primary">保存反馈</button></div></form></div>`);
}
