function audioRecoveryCard(item,form,context){if(item.error)return `<article class="review-card"><strong>${e(item.label)}</strong><p class="form-error">上次转写未完成：${e(item.error)}</p><p class="form-hint">原文字草稿仍保留。若要重新转写，请核对原客户 / 交流后上传原录音。</p><button class="button small" type="button" data-dismiss-audio-recovery="${e(item.key)}">知道了，清除失败提示</button></article>`;const applied=item.applied_to===context.target_key&&Number(item.applied_customer_id||0)===context.customer_id&&String(formValues(form).text||'').includes(item.transcript);return `<article class="review-card"><strong>${e(item.label)}</strong><p>${e(item.transcript.slice(0,180))}${item.transcript.length>180?'…':''}</p><button class="button small" type="button" data-restore-audio-recovery="${e(item.key)}" ${applied?'disabled':''}>${applied?'已恢复到当前草稿 · 保存后清除':'核对后恢复到本轮文字'}</button></article>`;}
function audioRecoveryHTML(form){const context=audioRecoveryContext(form),items=audioRecoveryItems().filter(item=>item.target_key===context.target_key);return items.length?`<section class="audio-section audio-recoveries"><h3>上次语音输入的保留项</h3><p class="form-hint">窗口切换时保留了转写状态。先核对原客户 / 交流，再恢复到本轮文字；保存成功后清除对应保留项。</p>${items.map(item=>audioRecoveryCard(item,form,context)).join('')}</section>`:'';}
function attachAudioRecoveries(dialog){const upload=$('#audio-upload-form',dialog);if(!upload)return;const target=document.getElementById(upload.dataset.transcriptTarget||'customer-command-text');if(!target?.form)return;const html=audioRecoveryHTML(target.form);if(html)upload.insertAdjacentHTML('afterend',html);}
function preserveLateAudioTranscript(context,transcript){const key=`${draftPrefix}audio-recovery:${newVisitRequestKey()}`;writeDraft(key,{kind:'audio_recovery',...context,transcript,created_at:Date.now()});notify(`原输入窗口已切换。转写已为“${context.label}”保留，回到原语音 / 复盘入口可核对后恢复。`);return key;}
function preserveLateAudioFailure(context,error){const key=`${draftPrefix}audio-recovery:${newVisitRequestKey()}`;writeDraft(key,{kind:'audio_recovery',...context,transcript:'',error:String(error),created_at:Date.now()});notify(`“${context.label}”的上次转写未完成，原文字草稿与失败提示已保留。回到原语音 / 复盘入口可查看并重新上传录音。`,true);return key;}
function restoreAudioRecovery(key){const item=readDraft(key);if(item?.kind!=='audio_recovery')throw new Error('这段保留的转写已处理，请查看原记录。');const form=document.getElementById(item.target_form_id);if(!form||form.isConnected===false)throw new Error('请回到原语音 / 复盘入口恢复这段转写。');const context=audioRecoveryContext(form);if(context.target_key!==item.target_key||context.customer_id!==Number(item.customer_id||0))throw new Error(`这段属于“${item.label}”。请先选择原客户 / 交流再恢复。`);const field=$('[name="text"]',form),raw=$('[name="original_transcript"]',form);if(!field)throw new Error('原文字输入框已变化，请重新打开后恢复。');if(item.applied_to===context.target_key&&String(field.value).includes(item.transcript)){notify('这段转写已在当前草稿中，保存后会清除对应保留项。');return;}field.value=field.value.trim()?`${field.value}\n\n${item.transcript}`:item.transcript;if(raw)raw.value=raw.value?`${raw.value}\n\n${item.transcript}`:item.transcript;saveDraft(form);writeDraft(key,{...item,applied_to:context.target_key,applied_customer_id:context.customer_id});notify('转写已恢复到原客户 / 交流草稿，请核对文字后保存。');field.focus();return form;}
