    recorder.ondataavailable=event=>{if(event.data.size)parts.push(event.data);if(state.audioCapabilities?.max_bytes&&parts.reduce((size,part)=>size+part.size,0)>=state.audioCapabilities.max_bytes*.95&&recorder.state==='recording')recorder.stop();};
