function observationMark(fact){return fact.basis==='observation'?'<span class="brief-observation">个人观察 · 待核实</span>':'';}
function visitBrief(profile,coaching={}){
  const brief=profile.brief||{},facts=profile.fields||[],contacts=(profile.contacts||[]).filter(contact=>!contact.archived);
  const customer=profile.customer||{},mainContact=contacts.find(contact=>Number(contact.id)===Number(customer.primary_contact_id))||contacts[0],latest=brief.recent_records?.[0],days=latest?Math.floor((Date.now()/1000-latest.created_at)/86400):null;
  const oneMinute=`<div class="brief-primary"><h4>一分钟看清这位客户</h4><p>主要对接：${e(mainContact?`${mainContact.name} · ${mainContact.role||'角色待确认'}`:'尚未明确')}<br>当前阶段：${e(stages[customer.stage]||'待确认')} · ${e(customerMoney(customer))}${customer.contact_cycle_days?`<br>建议联系间隔：${Number(customer.contact_cycle_days)} 天${days!==null&&days>=customer.contact_cycle_days?` · 已 ${days} 天未新增交流记录，可准备下一次联系`:''}`:''}${coaching.recommendation?`<br>${coaching.recommendation.stale?'上次建议目标':'下一步目标'}：${e(coaching.recommendation.objective)}`:''}</p></div>`;
  const priorities=['next_visit_goal','pain_points','requirements','crypto_needs','blockers'];const focus=priorities.map(key=>facts.find(f=>f.key===key)).filter(Boolean).slice(0,3);
  const preferences=contacts.flatMap(c=>(c.fields||[]).filter(f=>['concerns','communication_channel','contact_hours','detail_preference'].includes(f.key)).map(f=>({name:c.name,...f}))).slice(0,3);
  const missing=(brief.missing_fields||[]).slice(0,4).map(field=>typeof field==='string'?fieldLabel(field):field.label||fieldLabel(field.key));
  const open=brief.open_records||[],recent=brief.recent_records||[],tasks=brief.next_tasks||[];
  return `<section class="visit-brief"><div class="visit-brief-head"><span>${icon('leaf')}</span><div><span class="section-overline">拜访之前，花一分钟</span><h3>这位客户，下一步怎么推进</h3></div></div>${oneMinute}<div class="brief-block"><h4>先聊什么</h4>${focus.length?focus.map(f=>`<p><strong>${e(f.label||fieldLabel(f.key))}</strong>${e(f.value)}${observationMark(f)}</p>`).join(''):'<p class="brief-placeholder">还没有明确拜访目的，先记下客户当前最关心的问题。</p>'}</div><div class="brief-block"><h4>上次的事继续落实 <span>${open.length}</span></h4>${open.length?`<ul>${open.slice(0,3).map(r=>`<li><button class="inline-link" data-record="${Number(r.id)}">${e(r.title||r.content)}</button></li>`).join('')}</ul>`:'<p class="brief-placeholder">暂无未完成的关联事项。</p>'}${tasks.length?`<div class="brief-next">${icon('calendar')}<span>下次安排：${e(formatDate(tasks[0].remind_at,true))} · ${e(tasks[0].title)}</span></div>`:''}</div>${preferences.length?`<div class="brief-block"><h4>沟通时记得</h4>${preferences.map(f=>`<p><strong>${e(f.name)} · ${e(f.label||fieldLabel(f.key))}</strong>${e(f.value)}${observationMark(f)}</p>`).join('')}</div>`:''}${recent.length?`<div class="brief-block brief-recent"><h4>最近一次交流</h4><button class="inline-link" data-record="${Number(recent[0].id)}">${e(recent[0].title)}</button><p>${e((recent[0].content||recent[0].original_content||'').slice(0,180))}</p></div>`:''}${missing.length?`<p class="brief-missing">下次可顺便核实：${e(missing.join('、'))}</p>`:''}</section>`;
}

function phoneActions(phone){const safe=String(phone).replace(/[^0-9+*#]/g,'');return `<div class="contact-actions">${safe?`<a class="button small" href="tel:${e(safe)}">${e(phone)} · 拨号</a>`:`<span>${e(phone)}</span>`}<button type="button" class="button small" data-copy-phone="${e(phone)}">复制电话</button></div>`;}
