function draftCode(id){return /^C/i.test(String(id))?String(id):`C${id}`;}
function draftSummary(draft){return `<button class="draft-summary" data-customer-draft="${e(draft.id)}"><span class="draft-code">${e(draftCode(draft.id))}</span><span><strong>${e(draft.customer_name||'客户资料变更')}</strong><small>${draft.intent==='create'?'新建客户':'补充客户资料'}${draft.contact_name?` · ${e(draft.contact_name)}`:''} · ${Number(draft.changes?.length||0)} 项变更</small></span>${icon('right')}</button>`;}
