function showFeatureLoadError(label){
  const main=$('#main'),html=`<div id="feature-load-error" class="error-banner" role="alert"><span>${e(label)}功能没有加载完整。请刷新页面；若仍无法打开，请重启本机后台加载最新版本。</span><button type="button" class="button small" data-reload-app>刷新页面</button></div>`;
  const previous=$('#feature-load-error',main);if(previous)previous.outerHTML=html;else main.insertAdjacentHTML('afterbegin',html);
}
async function dispatchFeatureAction(button){
  const data=button.dataset||{},has=keys=>keys.some(key=>Object.hasOwn(data,key));
  const features=[
    {label:'秘书准备',handler:typeof handleSecretaryAction==='function'?handleSecretaryAction:null,owns:Object.keys(data).some(key=>key.startsWith('secretary'))},
    {label:'跟进历程',handler:typeof handleTimelineAction==='function'?handleTimelineAction:null,owns:has(['timelineReturn','timelineRemoveEvidence','timelineClearEvidence','timelineDismissReceipt','timelineOpenSource','timelineContext','customerTimeline','contactTimeline','timelineEvent','timelineCapture','timelineRefresh','timelinePage','timelineClearFilter','timelineDiscuss'])},
    {label:'客户关系与研究',handler:typeof handleAccountAction==='function'?handleAccountAction:null,owns:Object.keys(data).some(key=>key.startsWith('account')||key.startsWith('research'))||has(['projectRelationships','contactProjects'])},
  ];
  for(const feature of features){
    if(!feature.handler){if(feature.owns){showFeatureLoadError(feature.label);throw new Error(`${feature.label}功能未加载，请刷新页面或重启本机后台后再试。`);}continue;}
    if(await feature.handler(button))return true;
  }
  return false;
}
