async function backgroundRefresh(){
  if(!state.authenticated||document.hidden||state.refreshing||state.captureSaving||state.discussionSaving||$('#edit-dialog').open||$('#detail-dialog').open)return;
  if(document.activeElement?.matches('input,textarea,select'))return;
  state.refreshing=true;try{await loadView(true);if(state.view!=='dashboard'){const data=await api('/api/dashboard');updateConnection(data);}}catch{}finally{state.refreshing=false;}
}
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMaterialPoll();stopVisitPoll();stopCapturePoll();stopDiscussionPoll();stopCaptureDetailPoll();}else{backgroundRefresh();scheduleMaterialPoll();scheduleVisitPoll();scheduleCapturePoll();scheduleDiscussionPoll();scheduleCaptureDetailPoll();}});
setInterval(backgroundRefresh,20000);
(async()=>{try{const data=await api('/api/session');if(data.authenticated)await enterApp(data);else showLogin();}catch(error){$('#login-error').textContent=error.message;}})();
